// src/services/translation.service.ts
var TranslationService = class _TranslationService {
  constructor() {
    this.initialLang = localStorage.getItem("marcel_lang") || "fr";
    this.currentLang = signal(this.initialLang, ...ngDevMode ? [{ debugName: "currentLang" }] : (
      /* istanbul ignore next */
      []
    ));
    this.translations = computed(() => {
      return TRANSLATIONS2[this.currentLang()];
    }, ...ngDevMode ? [{ debugName: "translations" }] : (
      /* istanbul ignore next */
      []
    ));
    this.isEnglish = computed(() => this.currentLang() === "en", ...ngDevMode ? [{ debugName: "isEnglish" }] : (
      /* istanbul ignore next */
      []
    ));
    this.isFrench = computed(() => this.currentLang() === "fr", ...ngDevMode ? [{ debugName: "isFrench" }] : (
      /* istanbul ignore next */
      []
    ));
  }
  setLanguage(lang) {
    this.currentLang.set(lang);
    localStorage.setItem("marcel_lang", lang);
  }
  toggleLanguage() {
    const next = this.currentLang() === "fr" ? "en" : "fr";
    this.setLanguage(next);
  }
  /**
   * Helper pour formater un courriel bilingue selon la langue active
   */
  formatBilingualEmail(params) {
    const lang = this.currentLang();
    const divider = params.isHtml ? '<p style="margin-top: 12.0pt; margin-bottom: 12.0pt; line-height: normal; font-family: Calibri, sans-serif; font-size: 11.0pt; color: #000000;">______________________________________________________________________________</p>' : "\n\n______________________________________________________________________________\n\n";
    if (lang === "fr") {
      const headerNotice = params.isHtml ? '<p style="margin-top: 0cm; margin-bottom: 12.0pt; line-height: normal; font-family: Calibri, sans-serif; font-size: 11.0pt; color: #000000;"><strong>English message will follow.</strong></p>' : "English message will follow.\n\n";
      if (params.isHtml) {
        return `<div style="font-family: Calibri, sans-serif; font-size: 11.0pt; color: #000000; line-height: normal;">${headerNotice}${params.frBody}<p style="margin-top: 12.0pt;">${params.sigFr}</p>${divider}${params.enBody}<p style="margin-top: 12.0pt;">${params.sigEn}</p></div>`;
      } else {
        return `${headerNotice}${params.frBody}

${params.sigFr}${divider}${params.enBody}

${params.sigEn}`;
      }
    } else {
      const headerNotice = params.isHtml ? '<p style="margin-top: 0cm; margin-bottom: 12.0pt; line-height: normal; font-family: Calibri, sans-serif; font-size: 11.0pt; color: #000000;"><strong>Le message en fran\xE7ais suivra.</strong></p>' : "Le message en fran\xE7ais suivra.\n\n";
      if (params.isHtml) {
        return `<div style="font-family: Calibri, sans-serif; font-size: 11.0pt; color: #000000; line-height: normal;">${headerNotice}${params.enBody}<p style="margin-top: 12.0pt;">${params.sigEn}</p>${divider}${params.frBody}<p style="margin-top: 12.0pt;">${params.sigFr}</p></div>`;
      } else {
        return `${headerNotice}${params.enBody}

${params.sigEn}${divider}${params.frBody}

${params.sigFr}`;
      }
    }
  }
  static {
    this.\u0275fac = function TranslationService_Factory(__ngFactoryType__) {
      return new (__ngFactoryType__ || _TranslationService)();
    };
  }
  static {
    this.\u0275prov = /* @__PURE__ */ \u0275\u0275defineInjectable({ token: _TranslationService, factory: _TranslationService.\u0275fac, providedIn: "root" });
  }
};
(() => {
  (typeof ngDevMode === "undefined" || ngDevMode) && setClassMetadata(TranslationService, [{
    type: Injectable,
    args: [{
      providedIn: "root"
    }]
  }], null, null);
})();

