          const opt2OccupationsEn = isPluralAdmissionEn ? "your occupational choices (<strong>" + closedAdmissionOnlyJobs.join(", ") + "</strong>)" : "your occupational choice (<strong>" + closedAdmissionOnlyJobs.join(", ") + "</strong>)";
          const opt2ReferEn = isPluralAdmissionEn ? "your occupational choices" : "your occupational choice";
