      hEn += '<p class="mt-4 text-sm text-slate-600">If you do not take any action, your file will be automatically deactivated after 30 days.</p>\n';
      hEn += "<p>" + this.sharedState.getHtmlSignatureEn() + "</p>\n";
      const isEnglishActive = this.translationService.isEnglish();
