  getJobContractDuration(jobId) {
    const job = this.jobService.getJobById(jobId);
    if (!job || !job.contracts || job.contracts.length === 0)
      return 10;
    const pforContract = job.contracts.find((c) => (c.program || "").toUpperCase().includes("PFOR")) || job.contracts[0];
    if (pforContract && pforContract.duration) {
      const match = pforContract.duration.match(/(\d+)\s*an/);
      if (match)
        return parseInt(match[1], 10);
    }
    return 10;
  }
