  translateDateToEn(dateStr) {
    if (!dateStr)
      return "";
    const map2 = {
      "janvier": "January",
      "f\xE9vrier": "February",
      "mars": "March",
      "avril": "April",
      "mai": "May",
      "juin": "June",
      "juillet": "July",
      "ao\xFBt": "August",
      "septembre": "September",
      "octobre": "October",
      "novembre": "November",
      "d\xE9cembre": "December"
    };
    let result = dateStr;
    for (const [fr, en] of Object.entries(map2)) {
      result = result.replace(new RegExp(`\\b${fr}\\b`, "gi"), en);
    }
    return result;
  }
  getAvisFermetureSectionPlainFr() {
    let delaiLineFr = "";
    if (this.avisFermetureDelaiJours() === "autre") {
      const dateStr = this.avisFermetureDate().trim() || "xx";
      delaiLineFr = `\xC0 cet effet, nous vous accordons jusqu'au ${dateStr} pour effectuer les actions n\xE9cessaires.`;
    } else {
      const delai = this.avisFermetureDelaiJours() || "14";
      delaiLineFr = `\xC0 cet effet, nous vous accordons un d\xE9lai de ${delai} jours \xE0 compter de la date d'envoi de ce courriel pour effectuer les actions n\xE9cessaires.`;
    }
    const tasks = this.getAvisFermetureSelectedTasksFr();
    let tasksBlock = "";
    if (tasks.length > 0) {
      tasksBlock = "\n\nVoici les t\xE2ches \xE0 compl\xE9ter dans le d\xE9lai prescrit :\n" + tasks.map((t, i) => `${i + 1}- ${t}`).join("\n");
    } else {
      tasksBlock = "\n\nVoici les t\xE2ches \xE0 compl\xE9ter dans le d\xE9lai prescrit :\n1-\n\n2-";
    }
    return `Bonjour,

Par la pr\xE9sente, nous vous informons que votre dossier demeure incomplet \xE0 ce jour, certaines t\xE2ches requises n\u2019ayant pas \xE9t\xE9 compl\xE9t\xE9es.
${delaiLineFr}
\xC0 d\xE9faut de r\xE9gularisation dans ce d\xE9lai, nous proc\xE9derons \xE0 la fermeture de votre dossier sans autre avis.${tasksBlock}

Si vous avez des questions, n\u2019h\xE9sitez pas \xE0 communiquer avec moi.`;
  }
  getAvisFermetureSectionPlainEn() {
    let delaiLineEn = "";
    if (this.avisFermetureDelaiJours() === "autre") {
      const rawDate = this.avisFermetureDate().trim() || "xx";
      const dateStr = rawDate !== "xx" ? this.translateDateToEn(rawDate) : "xx";
      delaiLineEn = `To this end, we grant you until ${dateStr} to take the necessary actions.`;
    } else {
      const delai = this.avisFermetureDelaiJours() || "14";
      delaiLineEn = `To this end, we grant you a period of ${delai} days from the sending date of this email to take the necessary actions.`;
    }
    const tasks = this.getAvisFermetureSelectedTasksEn();
    let tasksBlock = "";
    if (tasks.length > 0) {
      tasksBlock = "\n\nHere are the tasks to complete within the prescribed timeframe:\n" + tasks.map((t, i) => `${i + 1}- ${t}`).join("\n");
    } else {
      tasksBlock = "\n\nHere are the tasks to complete within the prescribed timeframe:\n1-\n\n2-";
    }
    return `Hello,

We hereby inform you that your file remains incomplete to date, as certain required tasks have not been completed.
${delaiLineEn}
Failing regularization within this timeframe, we will proceed with closing your file without further notice.${tasksBlock}

If you have any questions, please do not hesitate to contact me.`;
  }
