  isSubsidizedEducationJob(job) {
    if (!job)
      return false;
    const title = (job.title || "").toUpperCase();
    const titleEn = (job.titleEn || "").toUpperCase();
    const programs = (job.contracts || []).map((c) => (c.program || "").toUpperCase()).join(" ");
    const subKeywords = [
      "PFOR",
      "PFS-MR",
      "PFOEP",
      "PFUMR",
      "PIES-MR",
      "PMEP",
      "ESNEM",
      "PFDM",
      "PFMD",
      "UTPNCM",
      "ROTP",
      "NOCP",
      "MMTP",
      "SUBVENTION"
    ];
    if (subKeywords.some((kw) => title.includes(kw) || titleEn.includes(kw) || programs.includes(kw)))
      return true;
    return false;
  }
